import {
  Suspense,
  lazy,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { FluentProvider } from "@fluentui/react-components";
import { ja } from "./strings/ja";
import { hsLightTheme, hsDarkTheme } from "./theme/fluentTheme";
import { useThemeMode } from "./theme/useThemeMode";
import { AppShell } from "./components/AppShell";
import { TitleBar } from "./components/TitleBar";
import { CommandBar } from "./components/CommandBar";
import { WaveformView } from "./components/WaveformView";
import { ScoreWorkspace } from "./components/ScoreWorkspace";
import { PropertiesPanel } from "./components/PropertiesPanel";
import {
  RequantizeDialog,
  requantizeSeed,
} from "./components/RequantizeDialog";
import { TransportBar } from "./components/TransportBar";
import { StatusBar } from "./components/StatusBar";
import { SettingsView } from "./components/SettingsView";
import { TranscriptionView } from "./components/TranscriptionView";
import { TranscriptionErrorView } from "./components/TranscriptionErrorView";
import { ExportDialog } from "./export/ExportDialog";
import { DiagnosticsSheet } from "./diagnostics/DiagnosticsSheet";
import { createDefaultExportPort } from "./export/port";
import type { ExportSource } from "./export/tauriPort";
import { exportErrorCode } from "./export/types";
import { createDefaultDiagnosticsPort } from "./diagnostics/port";
import { useAppSettings, type SettingsCategory } from "./settings/store";
import type { PitchView } from "./components/PitchSegmented";
import { createFixtureScoreDocument } from "./score/fixtureDocument";
import { scoreHandoffFromResult } from "./score/jobResult";
import {
  createEngineScoreDocument,
  engineDocumentFromResult,
} from "./score/xmlDocument";
import type { ScoreDocumentPort } from "./score/document";
import type { InspectorModel } from "./score/inspector";
import type { RhythmEditInvoker } from "./score/rhythmEdits";
import type {
  ScoreWorkspaceController,
  ScoreWorkspaceState,
} from "./score/controller";
import { openIssues } from "./score/review";
import { formatTimecode as formatScoreTimecode } from "./score/timecode";
import {
  createCommandRegistry,
  createCommandSurface,
  type CommandContext,
  type CommandSnapshot,
} from "./commands/registry";
import { KeyboardDispatcher } from "./keyboard/dispatcher";
import { useCommandKeyboard } from "./keyboard/useCommandKeyboard";
import { cycleFocusZone, focusZone } from "./focus/zones";
import { getShellInfo, isTauriRuntime } from "./tauri/bridge";
import {
  ImportController,
  parseProjectFile,
  type ImportState,
} from "./import/controller";
import { INITIAL_IMPORT_STATE } from "./import/controller";
import { loadRecentProjects, recordRecentProject } from "./import/recentProjects";
import { createImportPorts } from "./import/runtimePorts";
import { issueCopy, type ImportView } from "./import/ImportStates";
import { listenNativeDrop } from "./import/nativeDrop";
import { invoke } from "@tauri-apps/api/core";
import { buildProjectDocument } from "./import/project";
import { baseName } from "./import/formats";
import { CaptureController, type CaptureState } from "./capture/controller";
import {
  collectReferencedRecordingNames,
  getRecordingsInfo,
  pruneRecordings,
} from "./capture/recordings";
import { createCapturePort } from "./capture/runtimePorts";
import type { CaptureDeviceList, CaptureSource } from "./capture/types";
import {
  MediaElementTransport,
  SUPPORTED_RATES,
  type TransportSnapshot,
} from "./import/mediaTransport";
import {
  DEFAULT_TRANSCRIPTION_OPTIONS,
  type AudioFileRef,
  type TranscriptionOptions,
} from "./import/types";
import { buildTranscriptionParams } from "./import/transcriptionParams";
import { stageAudioForEngine } from "./import/staging";
import { formatTimecode } from "./import/format";
import { HsButton } from "./components/primitives/Button";
import { HsDialog } from "./components/primitives/Dialog";
import {
  regionVisibility,
  commandStateFor,
  SCREEN_STATES,
  type ScreenState,
} from "./workspace/screen";
import {
  TranscriptionSession,
  createDefaultSidecarPort,
  type EngineStatus,
} from "./sidecar";
import {
  inspectorHasContent,
  NO_SELECTION,
  type InspectorContent,
} from "./workspace/inspector";
import { useWorkspaceLayout } from "./workspace/layout";
import { initWindowGeometryPersistence } from "./workspace/windowGeometry";

type View = "workspace" | "settings";

/** "#/dev/gallery" — dev-only internal component gallery (UI-010). */
const GALLERY_HASH = "#/dev/gallery";
/** "#/dev/state/<screen>" — dev-only screen-state override so the
 *  responsive layout can be verified in every machine state (§27) before
 *  the real audio/score features land. No-op in packaged builds. */
const STATE_HASH_PREFIX = "#/dev/state/";
/**
 * "#/dev/transcribing" — dev-only entry that starts the shell in
 * AUDIO_READY and auto-invokes `score.transcribe` once mounted, so the
 * real UI-040 job flow (mock engine) runs end to end before UI-020's
 * file-open wiring lands. Unlike "#/dev/state/transcribing" (a static
 * layout preview) this runs an actual job.
 */
const DEV_TRANSCRIBING_HASH = "#/dev/transcribing";
// Lazy so the gallery (and its Fluent imports) stay out of the prod bundle.
const DevGallery = import.meta.env.DEV
  ? lazy(() => import("./dev/Gallery"))
  : null;

function screenFromHash(hash: string): ScreenState | null {
  if (!import.meta.env.DEV || !hash.startsWith(STATE_HASH_PREFIX)) return null;
  const name = hash.slice(STATE_HASH_PREFIX.length);
  return (SCREEN_STATES as readonly string[]).includes(name)
    ? (name as ScreenState)
    : null;
}

/** Japanese display name for a focus zone (for status announcements). */
function zoneName(id: string): string {
  const names: Record<string, string> = ja.commandFeedback.zoneNames;
  return names[id] ?? id;
}

/** Engine connection line for the status bar (解析エンジン: …). */
function engineStatusText(engine: EngineStatus): string {
  switch (engine) {
    case "ready":
      return ja.status.engineReady;
    case "starting":
      return ja.status.engineStarting;
    case "crashed":
      return ja.status.engineCrashed;
    case "unresponsive":
      return ja.status.engineUnresponsive;
    default:
      return ja.status.engineNotConnected;
  }
}

/**
 * HornScribe workspace shell (UI-011) driven by the UI-012 command
 * architecture (GUI_UX_SPEC §2/§21/§22/§23/§27). Information architecture:
 * single workspace, score is primary, properties collapse before the score
 * narrows, command overflow instead of horizontal scrolling, layout state
 * restored across restarts.
 *
 * The screen-state machine (§27) feeds the CommandSnapshot, so every
 * surface — command bar, transport, keyboard — agrees on enablement:
 * EMPTY mounts only 開く-level shell actions; 採譜 needs audio and is
 * disabled while transcribing; 要確認/書き出し need a score.
 */
export default function App() {
  const { mode, resolved, select } = useThemeMode();
  const [view, setView] = useState<View>("workspace");
  const [pitch, setPitch] = useState<PitchView>("concert");
  // UI-060: persisted settings (localStorage) + the two secondary surfaces
  // (書き出し dialog / 診断情報 sheet) that live outside the workspace.
  const { settings, update: updateSettings } = useAppSettings();
  const [exportOpen, setExportOpen] = useState(false);
  const [requantizeOpen, setRequantizeOpen] = useState(false);
  const [diagnosticsOpen, setDiagnosticsOpen] = useState(false);
  const [settingsFocus, setSettingsFocus] = useState<
    SettingsCategory | undefined
  >(undefined);
  // Ports are runtime-gated (mock in a browser, explicit-failure in the
  // Tauri shell until the engine spawn bridge lands — see export/port.ts).
  // #99: the Tauri port reads the live score document + audio name at
  // export time through this ref (state lives below; the port is
  // created once, so a ref keeps the getter fresh).
  const exportSourceRef = useRef<ExportSource | null>(null);
  const exportPort = useMemo(
    () => createDefaultExportPort(() => exportSourceRef.current),
    [],
  );
  const diagnosticsPort = useMemo(() => createDefaultDiagnosticsPort(), []);
  // User-specified tool paths (設定 → ツール) flow into every probe.
  const toolOverrides = useMemo(
    () => ({
      museScorePath: settings.museScorePath || undefined,
      ffmpegPath: settings.ffmpegPath || undefined,
    }),
    [settings.museScorePath, settings.ffmpegPath],
  );
  const [statusMessage, setStatusMessage] = useState<string>(ja.status.ready);
  const [shellDetail, setShellDetail] = useState<string | undefined>(
    ja.status.shellInfoLoading,
  );
  const [hash, setHash] = useState(() => window.location.hash);
  // Screen state machine (§27). The import flow (UI-020) drives
  // empty/openingAudio/audioReady/audioError/sourceMissing; the sidecar
  // session (UI-040) drives transcribing/transcriptionError/scoreReady.
  // Dev builds can override via "#/dev/state/<name>" or auto-start a real
  // job via "#/dev/transcribing".
  const [screen, setScreen] = useState<ScreenState>(() =>
    import.meta.env.DEV && window.location.hash === DEV_TRANSCRIBING_HASH
      ? "audioReady"
      : "empty",
  );
  // A canonical score exists — survives failed/cancelled retranscription
  // (issue rule: partial failure never destroys valid state).
  const [hasScore, setHasScore] = useState(false);
  const [engineRestarting, setEngineRestarting] = useState(false);
  const layout = useWorkspaceLayout();

  // The session is created once per App mount; the default port is the
  // mock outside Tauri and the gated port inside (src/sidecar/README.md).
  const session = useMemo(
    () => new TranscriptionSession({ portFactory: createDefaultSidecarPort }),
    [],
  );
  const [sessionSnap, setSessionSnap] = useState(() => session.getSnapshot());

  useEffect(() => {
    const unsub = session.subscribe(setSessionSnap);
    return () => {
      unsub();
      // App shutdown → graceful engine.shutdown (bounded, never throws).
      void session.dispose();
    };
  }, [session]);

  const job = sessionSnap.job;
  const jobPhase = job?.phase;

  // [UI-030] the document behind SCORE_READY+: built once a transcription
  // completes — identity + review issues come from the job result
  // (score/jobResult.ts); the notation body stays on the committed fixture
  // until the engine ships MusicXML through the same port.
  const [scoreDocument, setScoreDocument] =
    useState<ScoreDocumentPort | null>(null);
  const [inspectorModel, setInspectorModel] = useState<InspectorModel>({
    kind: "empty",
  });
  const [scoreState, setScoreState] = useState<ScoreWorkspaceState | null>(null);
  const scoreCtlRef = useRef<ScoreWorkspaceController | null>(null);

  // §27 transitions driven by the job lifecycle. Terminal phases are
  // consumed once (session.clearJob) — retry is never silent.
  useEffect(() => {
    if (!jobPhase) return;
    if (jobPhase === "completed") {
      setHasScore(true);
      // ENG-002: a real engine result carries MusicXML — build the
      // document from it. The mock/dev result carries none, so the
      // deterministic fixture stays the honest fallback there.
      const engineInput = engineDocumentFromResult(sessionSnap.lastResult);
      const handoff = scoreHandoffFromResult(sessionSnap.lastResult);
      const engineDoc =
        engineInput !== null
          ? createEngineScoreDocument({
              ...engineInput,
              issues: handoff?.issues ?? [],
            })
          : null;
      setScoreDocument(engineDoc ?? createFixtureScoreDocument(handoff));
      setScreen("scoreReady");
      setStatusMessage(ja.transcription.completed);
      session.clearJob();
    } else if (jobPhase === "cancelled") {
      setScreen(hasScore ? "scoreReady" : "audioReady");
      setStatusMessage(ja.transcription.cancelled);
      session.clearJob();
    }
    // `failed` also sets snap.failure — the screen mapping lives on the
    // failure flag below so crash/unresponsive land identically.
  }, [jobPhase, hasScore, session, sessionSnap.lastResult]);

  // §27: fail → TRANSCRIPTION_ERROR. Set by a terminal `failed` event
  // (job error) or by crash/unresponsive supervision while a job ran.
  useEffect(() => {
    if (sessionSnap.failure) setScreen("transcriptionError");
  }, [sessionSnap.failure]);

  /* ---- UI-020 import flow ---- */
  // The transport adapter (UI-004 contract) is created once per app; the
  // import controller feeds it decoded media sources on AUDIO_READY.
  const transport = useMemo(() => new MediaElementTransport(), []);
  const [transportSnap, setTransportSnap] =
    useState<TransportSnapshot | null>(null);
  const [importState, setImportState] =
    useState<ImportState>(INITIAL_IMPORT_STATE);
  const [recentProjects, setRecentProjects] = useState(() =>
    loadRecentProjects(),
  );
  const [nativeDrag, setNativeDrag] = useState(false);
  const [transcriptionOptions, setTranscriptionOptions] =
    useState<TranscriptionOptions>(DEFAULT_TRANSCRIPTION_OPTIONS);
  // 設定→採譜は採譜オプションの既定値: 新しい音源を開くたびに
  // 設定値でリセットする(表示だけの死んだ設定にしない)。
  useEffect(() => {
    if (!importState.audio) return;
    setTranscriptionOptions({
      ...DEFAULT_TRANSCRIPTION_OPTIONS,
      tempo: settings.tempoMode,
      tempoBpm: settings.tempoMode === "manual" ? settings.bpm : null,
      meter: settings.meter,
      minDuration: { eighth: "8", sixteenth: "16", thirtySecond: "32" }[
        settings.minDuration
      ],
      // 「三連符を使う」off は候補を生成しない none。on は既定の
      // region-gated 自動判定(auto)に任せる — always だと全拍に
      // 三連符候補が乗り既定挙動が変わるため。
      triplets: settings.triplets ? "auto" : "none",
    });
  }, [importState.audio, settings]);

  // #99: keep the export port's source getter current — the doc plus a
  // basename derived from the loaded audio's file name (extension
  // stripped), matching the ENG-001 `<basename>_<artifact>` policy.
  useEffect(() => {
    const fileName = importState.audio?.fileName ?? "";
    const stem = fileName.replace(/\.[^.]*$/, "");
    // #87: path-backed refs can be bundled into the export; in-browser
    // bytes (kind:"file" drops, pathless recordings) cannot be copied.
    const ref = importState.audio?.ref;
    const audioPath =
      ref?.kind === "path"
        ? ref.path
        : ref?.kind === "recording"
          ? (ref.path ?? null)
          : null;
    exportSourceRef.current = scoreDocument
      ? {
          doc: scoreDocument,
          basename: stem || scoreDocument.meta.title,
          audioPath,
          audioName: audioPath ? fileName || null : null,
        }
      : null;
  }, [scoreDocument, importState.audio]);

  // FEAT-001 (#60): capture session state (loopback / microphone).
  const [captureState, setCaptureState] =
    useState<CaptureState | null>(null);
  // #76: 録音開始前の「現在の音源を置き換える」確認ダイアログ。
  const [pendingCapture, setPendingCapture] =
    useState<CaptureSource | null>(null);
  // #73: 取り込みデバイス選択(capture_devices の結果)。
  const [captureDevices, setCaptureDevices] =
    useState<CaptureDeviceList | null>(null);

  const importer = useMemo(
    () =>
      new ImportController(
        createImportPorts(),
        {
          onScreenChange: (s) => setScreen(s),
          onState: (s) => setImportState(s),
          onRecentChange: (entries) => setRecentProjects([...entries]),
          announce: setStatusMessage,
          onAudioReady: (audio) => {
            // Fire-and-forget: a media failure flips the transport snapshot
            // to "error" — the status line already carries the outcome.
            void transport.load(audio.mediaSource).catch(() => undefined);
          },
          onProjectScoreReady: (result) => {
            // #106: the saved extras mirror the completed-job result —
            // rebuild the document and land on SCORE_READY without
            // re-transcribing. Malformed extras fall back to the
            // fixture document only in dev; with a real result null
            // means no usable MusicXML, so keep the audio-only state.
            const input = engineDocumentFromResult(result);
            if (!input) return;
            const handoff = scoreHandoffFromResult(result);
            const doc = createEngineScoreDocument({
              ...input,
              issues: handoff?.issues ?? [],
            });
            if (!doc) return;
            setHasScore(true);
            setScoreDocument(doc);
            // Keep the SOURCE_MISSING card on screen when the audio
            // still needs relinking — the score is ready underneath
            // and lands when the relink succeeds.
            setScreen((s) => (s === "sourceMissing" ? s : "scoreReady"));
          },
        },
        // Recent-project MRU persists in localStorage (web + webview).
        typeof window !== "undefined" ? window.localStorage : null,
      ),
    [transport],
  );

  // #128 (§26 last project): on launch, reopen the project at the top
  // of the MRU — the same entry the 最近のプロジェクト list shows
  // first. Runs once on the initial empty screen; browser dev has no
  // durable project paths so it skips quietly there.
  const restoredProjectRef = useRef(false);
  useEffect(() => {
    if (restoredProjectRef.current) return;
    restoredProjectRef.current = true;
    if (!isTauriRuntime()) return;
    if (screen !== "empty") return;
    const last = recentProjects[0];
    if (!last?.path) return;
    void importer.openProject(last);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- launch-only restore
  }, []);

  // FEAT-001: the capture controller pushes recorded audio straight into
  // the import flow — a finished take lands as AUDIO_READY exactly like a
  // picked file (single-document app: the new source replaces the old).
  const capture = useMemo(
    () =>
      new CaptureController(createCapturePort(), {
        onState: (s) => setCaptureState(s),
        announce: setStatusMessage,
        onCaptureComplete: ({ path, bytes, fileName, source, mimeType }) => {
          // Tauri: 録音は appDataDir/recordings/ に保存済み(#70)なので
          // path を渡し、import 側で読み直す。ブラウザ dev 等で path が
          // 無い場合は bytes → Blob を渡す。
          const blob = bytes
            ? new Blob(
                [
                  new Uint8Array(
                    new Uint8Array(
                      bytes.buffer,
                      bytes.byteOffset,
                      bytes.byteLength,
                    ),
                  ),
                ],
                { type: mimeType ?? "audio/wav" },
              )
            : undefined;
          void importer.importRecording({
            kind: "recording",
            name: fileName,
            source,
            path,
            blob,
          });
        },
      }),
    [importer],
  );
  useEffect(() => () => capture.dispose(), [capture]);

  // 設定→再生: 標準再生速度はライブ設定なので即時反映する
  // (transport.setRate は [0.25,4] にクランプ済み)。
  useEffect(() => {
    transport.setRate(settings.playbackRate);
  }, [transport, settings.playbackRate]);

  // #87: 保持日数ポリシー — 起動時に一度だけ古い録音を削除する。
  // settings.recordingsRetentionDays は起動時の値で確定(途中変更は
  // 次回起動から有効)。削除件数はステータスバーで知らせる。
  useEffect(() => {
    const days = settings.recordingsRetentionDays;
    if (days <= 0) return;
    /* #132: recordings a saved project still references are excluded
     * from the retention sweep — deleting them would leave the project
     * openable but source-less. Only the recordings dir is protected;
     * unreadable projects fail open (their refs stay unknown). */
    void (async () => {
      const ports = createImportPorts();
      const info = await getRecordingsInfo();
      const keep = await collectReferencedRecordingNames({
        readProjectBytes: ports.readProjectBytes,
        entries: loadRecentProjects(),
        dir: info?.dir ?? null,
        sourcePathOf: async (blob) =>
          parseProjectFile(await blob.arrayBuffer(), "").sourcePath,
      });
      const n = await pruneRecordings(days, keep);
      if (n > 0) setStatusMessage(ja.settings.recordingsPruned(n));
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- run once
  }, []);

  // #81: 録音中にアプリを閉じると録音は失われる。WebView2/Tauri でも
  // beforeunload の preventDefault は閉じる確認として扱われるため、
  // 録音中だけガードを掛ける(録音していない時の常駐確認はしない)。
  const recordingActive = captureState?.phase === "recording";
  useEffect(() => {
    if (!recordingActive) return;
    const guard = (e: BeforeUnloadEvent) => {
      e.preventDefault();
    };
    window.addEventListener("beforeunload", guard);
    return () => window.removeEventListener("beforeunload", guard);
  }, [recordingActive]);

  // #73: デバイス一覧はメニューを開く度に取り直す(抜き差しに追従)。
  const refreshCaptureDevices = useCallback(() => {
    void capture
      .listDevices()
      .then(setCaptureDevices)
      .catch(() => setCaptureDevices(null));
  }, [capture]);

  // #76: 録音は現在の音源(と楽譜)を置き換える単一ドキュメントのため、
  // 既に音源がある時は開始前に確認する。録音中に演奏が鳴っていると
  // ループバック/マイクに混入するので、開始時に audition は切る。
  const requestCapture = useCallback(
    (source: CaptureSource) => {
      if (importState.audio || scoreDocument) {
        setPendingCapture(source);
        return;
      }
      if (scoreState?.auditionEnabled) scoreCtlRef.current?.toggleAudition();
      void capture.start(source);
    },
    [capture, importState.audio, scoreDocument, scoreState?.auditionEnabled],
  );
  const confirmCapture = useCallback(() => {
    const source = pendingCapture;
    setPendingCapture(null);
    if (!source) return;
    if (scoreState?.auditionEnabled) scoreCtlRef.current?.toggleAudition();
    void capture.start(source);
  }, [capture, pendingCapture, scoreState?.auditionEnabled]);

  const regions = regionVisibility(screen);

  // [UI-030] Feature inspector model → the shell's selection contract: the
  // panel auto-opens on real selections and stays closed otherwise (§6).
  const inspector: InspectorContent = useMemo(
    () =>
      inspectorModel.kind === "note"
        ? { kind: "note", noteId: inspectorModel.canonicalId ?? "" }
        : NO_SELECTION,
    [inspectorModel],
  );
  const propertiesVisible = regions.properties && layout.propertiesOpen;
  // Open-issue count prefers the live workspace mirror (UI-050: it tracks
  // decisions as they resolve); then the document's static list; then the
  // job result count for the window before the document mounts; the
  // dev-state REVIEWING placeholder stays so its surfaces can be reviewed.
  const reviewCount =
    scoreState?.openIssueCount ??
    (scoreDocument
      ? openIssues(scoreDocument.reviewIssues()).length
      : sessionSnap.reviewIssueCount > 0
        ? sessionSnap.reviewIssueCount
        : screen === "reviewing"
          ? 12
          : 0);

  // The registry is static: predicates read the snapshot, not React state.
  const registry = useMemo(() => createCommandRegistry(), []);

  // Screen machine → command snapshot (§23). Playback fields mirror the
  // transport adapter (UI-020) or, when no media source is loaded, the
  // score clock (UI-030 dev/fixture playback); isTranscribing keeps
  // score-writing commands disabled while a transcription runs (§5).
  const snapshot = useMemo<CommandSnapshot>(
    () => ({
      ...commandStateFor(screen),
      hasScore: commandStateFor(screen).hasScore && scoreDocument !== null,
      isPlaying:
        transportSnap?.status === "playing" ||
        (scoreState?.isPlaying ?? false),
      loopEnabled:
        transportSnap?.loop != null || (scoreState?.loopEnabled ?? false),
      pitch,
      // UI-050: undo/redo reach the score workspace's review/edit history.
      canUndo: scoreState?.canUndo ?? false,
      canRedo: scoreState?.canRedo ?? false,
      hasSelection: scoreState?.hasSelection ?? false,
      // #113: the waveform range selection (AUDIO_READY) is Esc-clearable
      // like a score selection (spec 8).
      hasWaveformSelection:
        screen === "audioReady" && transcriptionOptions.range === "selection",
      reviewOpen: scoreState?.reviewOpen ?? screen === "reviewing",
      reviewCount,
      view,
      // FEAT-001: recording + audition gates for the command registry.
      isRecording: captureState?.phase === "recording",
      isRecordingPaused:
        captureState?.phase === "recording" && captureState.paused,
      auditionEnabled: scoreState?.auditionEnabled ?? false,
    }),
    [screen, scoreDocument, transportSnap, scoreState, pitch, reviewCount, view, captureState, transcriptionOptions],
  );

  // Whether the media transport carries a loaded source — then it is the
  // authoritative clock and the score follows via the transport prop
  // (UI-005 one-clock contract). Otherwise transport commands fall back to
  // the score clock (dev/fixture playback with no audio loaded).
  const mediaLive =
    transportSnap != null && transportSnap.status !== "empty";

  // §8 §-seek transport step (GUI_UX_SPEC §9: ←/→ 5 seconds).
  const seekBy = useCallback(
    (delta: number) => {
      void transport
        .seek(transport.getCurrentTime() + delta)
        .catch(() => undefined);
      setStatusMessage(
        ja.import.feedback.position(
          formatTimecode(transport.getCurrentTime()),
        ),
      );
    },
    [transport],
  );

  // #100: プロジェクトを保存 — pick a path, build the schema-v1
  // document, and let the engine validate + atomically write it. The
  // flow is async behind a fire-and-forget command entry.
  const saveProjectFlow = useCallback(async () => {
    const doc = scoreDocument;
    if (!doc) {
      setStatusMessage(ja.notifications.projectSaveFailed);
      return;
    }
    if (!isTauriRuntime()) {
      // Browser dev has no save picker — the honest limitation, not a
      // silent no-op (same posture as the other Tauri-only commands).
      setStatusMessage(ja.notifications.projectSaveUnsupported);
      return;
    }
    try {
      const project = await buildProjectDocument({
        audio: importState.audio,
        doc,
        result: sessionSnap.lastResult,
      });
      if (!project) {
        setStatusMessage(ja.notifications.projectSaveUnsupported);
        return;
      }
      const fileName = importState.audio?.fileName ?? "score";
      const suggested = fileName.replace(/\.[^.]*$/, "") || "score";
      const path = await invoke<string | null>("project_save_path", {
        suggestedName: `${suggested}.hornscribe.json`,
      });
      if (!path) return; // cancelled — no announcement needed
      const res = await session.saveProject(path, project);
      const name = res.path.split(/[\\/]/).pop() ?? res.path;
      setRecentProjects(recordRecentProject({ name, path: res.path }));
      setStatusMessage(ja.notifications.projectSaved);
    } catch {
      setStatusMessage(ja.notifications.projectSaveFailed);
    }
  }, [scoreDocument, importState.audio, sessionSnap.lastResult, session]);

  // #115 (spec 13): engine rhythm edits — the score workspace delegates
  // to the live engine's score.edit; the same worker that produced the
  // score re-realizes the edited measures (one worker, one caller, so
  // no extra spawn cost beyond the lazy ensureEngine).
  const applyRhythmEdit = useCallback<RhythmEditInvoker>(
    (scoreDocPayload, op) => session.applyScoreEdit(scoreDocPayload, op),
    [session],
  );

  const ctx = useMemo<CommandContext>(
    () => ({
      openAudio: () => void importer.openViaDialog(),
      transcribe: () => {
        // §27 AUDIO_READY → TRANSCRIBING. The job lifecycle effects own
        // every later transition; a failed start lands on the §20 surface.
        setScreen("transcribing");
        setStatusMessage(ja.transcription.start);
        // #86: browser-held bytes (kind:"file" drops, pathless
        // recordings) are staged to a temp file first so the real
        // engine gets a readable audioPath; refs already on disk
        // return null from staging and keep their own path.
        void stageAudioForEngine(importState.audio)
          .then((staged) =>
            session.startTranscription(
              buildTranscriptionParams(
                importState.audio,
                transcriptionOptions,
                staged,
                settings.backend,
              ),
            ),
          )
          .catch(() => {
            /* failure flag drives the error surface */
          });
      },
      cancelTranscription: () => {
        // Cooperative job.cancel — the terminal `cancelled` event is the
        // real transition; the button shows キャンセルしています… until then.
        session.cancelTranscription().catch(() => {
          /* JOB_NOT_FOUND races are ignored in the session; other
            failures surface through snap.failure/engine state */
        });
      },
      togglePlayPause: () => {
        if (transport.getSnapshot().status !== "empty") {
          // [UI-020] real audio clock — the score follows it through the
          // transport prop mirror (ScoreReadyWorkspace sync effect).
          if (transport.getSnapshot().status === "playing") {
            transport.pause();
            setStatusMessage(ja.import.feedback.paused);
          } else {
            void transport.play().catch(() => undefined);
            setStatusMessage(ja.import.feedback.playing);
          }
        } else {
          // No audio source loaded — the score clock is the transport
          // (fixture/dev playback, UI-030).
          const c = scoreCtlRef.current;
          if (c) c.togglePlayPause();
          else setStatusMessage(ja.score.empty);
        }
      },
      stop: () => {
        if (transport.getSnapshot().status !== "empty") {
          transport.stop();
          setStatusMessage(ja.import.feedback.stopped);
        } else {
          const c = scoreCtlRef.current;
          if (c) c.stop();
          else setStatusMessage(ja.score.empty);
        }
      },
      jumpBack: () => {
        if (transport.getSnapshot().status !== "empty")
          seekBy(-settings.skipSeconds);
        else scoreCtlRef.current?.jumpBy(-settings.skipSeconds * 1000);
      },
      jumpForward: () => {
        if (transport.getSnapshot().status !== "empty")
          seekBy(settings.skipSeconds);
        else scoreCtlRef.current?.jumpBy(settings.skipSeconds * 1000);
      },
      seekToStart: () => {
        if (transport.getSnapshot().status !== "empty") {
          void transport.seek(0).catch(() => undefined);
          setStatusMessage(
            ja.import.feedback.position(formatTimecode(0)),
          );
        } else {
          scoreCtlRef.current?.seekToStart();
        }
      },
      seekToEnd: () => {
        if (transport.getSnapshot().status !== "empty") {
          void transport
            .seek(transport.getDuration())
            .catch(() => undefined);
          setStatusMessage(
            ja.import.feedback.position(
              formatTimecode(transport.getDuration()),
            ),
          );
        } else {
          scoreCtlRef.current?.seekToEnd();
        }
      },
      // Loop arming is score-side when a score exists (UI-030 owns the
      // range contract: the score clock wraps inside the range and the
      // score draws passage marks). #113: the media transport mirrors the
      // same range so the *audio* loops too - and before any score exists
      // (AUDIO_READY) the loop button arms the media A-B loop directly,
      // over the waveform selection when one is committed.
      toggleLoop: () => {
        const c = scoreCtlRef.current;
        if (c) {
          c.toggleLoop();
          const range = c.loopRange?.();
          transport.setLoop(
            range
              ? { start: range.startMs / 1000, end: range.endMs / 1000 }
              : null,
          );
          return;
        }
        if (transportSnap && transportSnap.status !== "empty") {
          if (transportSnap.loop) {
            transport.setLoop(null);
            setStatusMessage(ja.commandFeedback.loopOff);
          } else {
            const sel =
              transcriptionOptions.range === "selection" &&
              transcriptionOptions.selectionStartSec != null &&
              transcriptionOptions.selectionEndSec != null
                ? {
                    start: transcriptionOptions.selectionStartSec,
                    end: transcriptionOptions.selectionEndSec,
                  }
                : { start: 0, end: transportSnap.duration };
            transport.setLoop(sel);
            setStatusMessage(ja.commandFeedback.loopOn);
          }
        } else {
          setStatusMessage(ja.commandFeedback.disabled);
        }
      },
      // FEAT-001: capture + score audition commands.
      captureSystemAudio: () => {
        requestCapture("loopback");
      },
      captureMicrophone: () => {
        requestCapture("microphone");
      },
      stopCapture: () => {
        void capture.stop();
      },
      cancelCapture: () => {
        void capture.cancel();
      },
      pauseCapture: () => {
        void capture.pause();
      },
      resumeCapture: () => {
        void capture.resume();
      },
      toggleScoreAudition: () => {
        const c = scoreCtlRef.current;
        if (c) c.toggleAudition();
        else setStatusMessage(ja.commandFeedback.disabled);
      },
      toggleSourceMute: () => {
        transport.setMuted(!(transportSnap?.muted ?? false));
        setStatusMessage(
          transportSnap?.muted
            ? ja.commandFeedback.unmutedSource
            : ja.commandFeedback.mutedSource,
        );
      },
      setPitchView: (v) => {
        setPitch(v);
        setStatusMessage(
          v === "concert"
            ? ja.commandFeedback.pitchConcert
            : ja.commandFeedback.pitchHornF,
        );
      },
      openReview: () => scoreCtlRef.current?.openReview(),
      reviewNext: () => scoreCtlRef.current?.reviewNext(),
      reviewPrevious: () => scoreCtlRef.current?.reviewPrevious(),
      // UI-050 review actions — all live in the score workspace session.
      reviewAccept: () => scoreCtlRef.current?.reviewAccept(),
      reviewDismiss: () => scoreCtlRef.current?.reviewDismiss(),
      reviewPlaySource: () => scoreCtlRef.current?.reviewPlaySource(),
      reviewPitchUp: () => scoreCtlRef.current?.reviewPitch(1),
      reviewPitchDown: () => scoreCtlRef.current?.reviewPitch(-1),
      reviewDeleteOrRestore: () =>
        scoreCtlRef.current?.reviewDeleteOrRestore(),
      exitReview: () => scoreCtlRef.current?.exitReview(),
      undo: () => {
        const c = scoreCtlRef.current;
        if (c) c.undo();
        else setStatusMessage(ja.commandFeedback.nothingToUndo);
      },
      redo: () => {
        const c = scoreCtlRef.current;
        if (c) c.redo();
        else setStatusMessage(ja.commandFeedback.nothingToRedo);
      },
      openExport: () => setExportOpen(true),
      // §13 高度編集: open the live score (current pitch view, edits
      // included) in the MuseScore GUI. The port resolves the detected/
      // user-pinned executable; missing MuseScore announces the 設定 →
      // ツール recovery path instead of a dead menu item.
      openInMuseScore: () => {
        void exportPort
          .openInMuseScore?.(pitch, toolOverrides)
          .then(() => setStatusMessage(ja.commandFeedback.museScoreOpened))
          .catch((err: unknown) =>
            setStatusMessage(
              exportErrorCode(err) === "MUSESCORE_UNAVAILABLE"
                ? ja.commandFeedback.museScoreMissing
                : ja.commandFeedback.museScoreFailed,
            ),
          );
      },
      // #100: プロジェクトを保存 — pick a path (Tauri) then hand the
      // schema-v1 document to the engine's project.save. In a plain
      // browser there is no save picker, so the command announces the
      // honest limitation instead of faking a write.
      saveProject: () => {
        void saveProjectFlow();
      },
      zoomScoreIn: () => scoreCtlRef.current?.zoomIn(),
      zoomScoreOut: () => scoreCtlRef.current?.zoomOut(),
      zoomScoreFit: () => scoreCtlRef.current?.zoomFit(),
      clearSelection: () => scoreCtlRef.current?.clearSelection(),
      // #113: Esc on a waveform selection drops the committed range and
      // returns the transcription-range option to "all" (spec 8).
      clearWaveformSelection: () => {
        if (transcriptionOptions.range === "selection") {
          setTranscriptionOptions({ ...transcriptionOptions, range: "all" });
        }
      },
      // #114: score note navigation + direct edits (spec 10/13).
      selectAdjacentNote: (direction) =>
        scoreCtlRef.current?.selectAdjacentNote?.(direction),
      editSelectedPitch: (delta) =>
        scoreCtlRef.current?.editSelectedPitch?.(delta),
      toggleSelectedDeleted: () =>
        scoreCtlRef.current?.toggleSelectedDeleted?.(),
      toggleSelectedEnharmonic: () =>
        scoreCtlRef.current?.toggleSelectedEnharmonic?.(),
      // #115: engine rhythm edits (spec 13) — duration ladder, onset
      // grid shift, tie toggle. The workspace runs them through the
      // serialized score.edit queue; these just forward.
      noteDurationScale: (power) =>
        scoreCtlRef.current?.noteDurationScale?.(power),
      shiftSelectedOnset: (steps) =>
        scoreCtlRef.current?.shiftSelectedOnset?.(steps),
      toggleSelectedTie: () =>
        scoreCtlRef.current?.toggleSelectedTie?.(),
      // #130 (spec 14): quantization-settings dialog — app-owned
      // surface; the workspace controller applies the requantize edit.
      openRequantizeDialog: () => setRequantizeOpen(true),
      // #131 (spec 13 post-MVP): split/merge via the workspace.
      splitSelectedNote: () =>
        scoreCtlRef.current?.splitSelectedNote?.(),
      mergeSelectedNotes: () =>
        scoreCtlRef.current?.mergeSelectedNotes?.(),
      openSettings: () => {
        setSettingsFocus(undefined);
        setView("settings");
      },
      openDiagnostics: () => setDiagnosticsOpen(true),
      // F6 / Shift+F6 region cycling (§22) — owned by focus/zones.ts; these
      // are the only fully-working transport-independent commands so far.
      focusNextRegion: () => {
        const zone = cycleFocusZone(1);
        if (zone) {
          setStatusMessage(ja.commandFeedback.focusMoved(zoneName(zone)));
        }
      },
      focusPreviousRegion: () => {
        const zone = cycleFocusZone(-1);
        if (zone) {
          setStatusMessage(ja.commandFeedback.focusMoved(zoneName(zone)));
        }
      },
      announce: setStatusMessage,
    }),
    [importer, transport, seekBy, session, capture, requestCapture, transportSnap, importState.audio, transcriptionOptions, settings.skipSeconds, settings.backend, saveProjectFlow, pitch, toolOverrides, exportPort],
  );

  // The dispatcher reads the snapshot lazily per key event, so it must see
  // the latest render's value even though the listener is stable.
  const snapshotRef = useRef(snapshot);
  snapshotRef.current = snapshot;
  const dispatcher = useMemo(
    () =>
      new KeyboardDispatcher({
        registry,
        getSnapshot: () => snapshotRef.current,
        context: ctx,
      }),
    [registry, ctx],
  );
  useCommandKeyboard(dispatcher);

  // One render-scoped invocation surface shared by command bar, transport
  // and any other component — buttons never call services directly.
  const commands = useMemo(
    () => createCommandSurface(registry, ctx, snapshot),
    [registry, ctx, snapshot],
  );

  // Closing the panel returns focus to the score region when the focus was
  // inside the panel (§22 focus discipline); if it was closed from the
  // overflow menu, focus stays where it is.
  const closeProperties = useCallback(() => {
    const focusInside =
      document
        .querySelector('.hs-properties')
        ?.contains(document.activeElement) ?? false;
    layout.setPropertiesOpen(false);
    if (focusInside) {
      requestAnimationFrame(() => focusZone("score"));
    }
  }, [layout]);

  // §6: the panel opens itself when a real selection exists; with nothing
  // selected it stays closed until the user reopens it manually.
  useEffect(() => {
    if (
      inspectorHasContent(inspector) &&
      regions.properties &&
      !layout.propertiesOpen
    ) {
      layout.setPropertiesOpen(true);
    }
  }, [inspector, regions.properties, layout]);

  // 採譜 start routes through the command surface — the registry decides
  // (disabled → honest announcement, never a silent no-op). Cancellation
  // is owned by TranscriptionView via score.cancelTranscription (§5).
  const transcribeClicked = useCallback(() => {
    if (!commands.invoke("score.transcribe")) {
      setStatusMessage(ja.commandFeedback.disabled);
    }
  }, [commands]);

  // Hash routing: internal dev gallery + dev screen-state override. The
  // product shell is a single workspace (§2), not a page router.
  useEffect(() => {
    const onHashChange = () => {
      const h = window.location.hash;
      setHash(h);
      const forced = screenFromHash(h);
      if (forced) {
        // Score states need a document — the deterministic fixture adapter
        // supplies one until engine output flows through the job result.
        if (commandStateFor(forced).hasScore) {
          setHasScore(true);
          setScoreDocument((doc) => doc ?? createFixtureScoreDocument());
        }
        setScreen(forced);
        setView("workspace");
      }
    };
    window.addEventListener("hashchange", onHashChange);
    onHashChange();
    return () => window.removeEventListener("hashchange", onHashChange);
  }, []);

  // Dev-only entry: "#/dev/transcribing" auto-starts a real job once the
  // shell is up so the whole TRANSCRIBING flow can be reviewed directly.
  const devAutoStarted = useRef(false);
  useEffect(() => {
    if (
      import.meta.env.DEV &&
      hash === DEV_TRANSCRIBING_HASH &&
      !devAutoStarted.current
    ) {
      devAutoStarted.current = true;
      commands.invoke("score.transcribe");
    }
  }, [hash, commands]);

  // §26 session restore: window geometry (size/position) persists across
  // restarts; panel sizes/visibility persist via useWorkspaceLayout.
  useEffect(() => {
    let alive = true;
    let unlisten: (() => void) | undefined;
    void initWindowGeometryPersistence().then((u) => {
      if (alive) unlisten = u;
      else u();
    });
    return () => {
      alive = false;
      unlisten?.();
    };
  }, []);

  // §27 SCORE_READY ⇄ REVIEWING (UI-050): the review bar lives inside the
  // score workspace, so the screen machine mirrors its open flag — region
  // chrome, command predicates (reviewOpen) and the dev-state surface all
  // read the same truth. Transitions are deliberately limited to the
  // scoreReady/reviewing pair so EXPORTING is never hijacked.
  const scoreReviewOpen = scoreState?.reviewOpen;
  useEffect(() => {
    if (screen === "scoreReady" && scoreReviewOpen === true) {
      setScreen("reviewing");
    } else if (screen === "reviewing" && scoreReviewOpen === false) {
      setScreen("scoreReady");
    }
  }, [screen, scoreReviewOpen]);

  // Prove the JS↔Rust IPC channel early; populates the status area.
  useEffect(() => {
    let alive = true;
    getShellInfo().then((info) => {
      if (!alive) return;
      setShellDetail(
        info ? `v${info.version}` : undefined, // browser dev: no shell info
      );
      setStatusMessage(ja.status.ready);
    });
    return () => {
      alive = false;
    };
  }, []);

  // Transport adapter → low-frequency snapshot for playhead + transport
  // bar (media timeupdate cadence, no rAF — see mediaTransport.ts header).
  useEffect(() => {
    const unsubscribe = transport.subscribe(setTransportSnap);
    setTransportSnap(transport.getSnapshot());
    return () => {
      unsubscribe();
      transport.dispose();
    };
  }, [transport]);

  // Native file drop (Tauri `dragDropEnabled`): enter/over light the drop
  // affordance on the score region, drop imports the first supported path.
  // Outside the webview this resolves to a no-op (HTML5 drop covers dev).
  useEffect(() => {
    let alive = true;
    let unlisten: (() => void) | undefined;
    void listenNativeDrop((payload) => {
      if (payload.type === "enter" || payload.type === "over") {
        setNativeDrag(true);
      } else if (payload.type === "leave") {
        setNativeDrag(false);
      } else {
        setNativeDrag(false);
        // 録音中のドロップは onDropFiles と同じゲート — 取り込み済みの
        // 録音を黙って上書きしない。
        if (captureState?.phase === "recording") return;
        const refs: AudioFileRef[] = payload.paths.map((path) => ({
          kind: "path",
          path,
          name: baseName(path),
        }));
        void importer.importRefs(refs);
      }
    }).then((u) => {
      if (alive) unlisten = u;
      else u();
    });
    return () => {
      alive = false;
      unlisten?.();
    };
  }, [importer, captureState?.phase]);

  // Assembled once per render for the import-owned score bodies
  // (ImportStates.tsx) — keeps ScoreWorkspace's prop surface small.
  const importView = useMemo<ImportView>(
    () => ({
      audio: importState.audio,
      openingLabel: importState.openingLabel,
      openingKind: importState.openingKind,
      issue: importState.issue,
      sourceMissing: importState.sourceMissing,
      recentProjects,
      options: transcriptionOptions,
      onOpenAudio: () => void importer.openViaDialog(),
      onOpenProject: (entry) => void importer.openProject(entry),
      onPickRelink: () => void importer.pickRelinkSource(),
      onDismissError: () => importer.dismiss(),
      onOptionsChange: setTranscriptionOptions,
      // FEAT-001: EMPTY state capture entry points.
      captureState,
      onStartCapture: (source) => {
        requestCapture(source);
      },
    }),
    [importState, recentProjects, transcriptionOptions, importer, captureState, requestCapture],
  );

  const theme = resolved === "dark" ? hsDarkTheme : hsLightTheme;
  // Dev-only route: the gallery renders in place of the shell and never
  // appears in product navigation.
  const showGallery = DevGallery != null && hash === GALLERY_HASH;

  return (
    // .hs-provider fixes the UI-009 latent bug: the FluentProvider wrapper
    // div had no definite height, so `height:100%` on .hs-shell collapsed
    // to content height. The provider now owns the full viewport.
    <FluentProvider theme={theme} className="hs-provider">
      {showGallery ? (
        <Suspense fallback={null}>
          <DevGallery themeMode={mode} onThemeMode={select} />
        </Suspense>
      ) : (
        <AppShell>
          {/* Document identity follows the loaded source audio (§2). */}
          <TitleBar documentTitle={importState.audio?.fileName} />
          {view === "settings" ? (
            <div className="hs-settings-wrap">
              <SettingsView
                themeMode={mode}
                onThemeMode={select}
                onBack={() => setView("workspace")}
                settings={settings}
                onSettingsChange={updateSettings}
                diagnosticsPort={diagnosticsPort}
                exportPort={exportPort}
                onOpenDiagnostics={() => setDiagnosticsOpen(true)}
                onAnnounce={setStatusMessage}
                focusCategory={settingsFocus}
              />
            </div>
          ) : (
            <>
              <CommandBar
                commands={commands}
                pitch={pitch}
                screen={screen}
                reviewCount={reviewCount}
                compact={layout.breakpoint === "compact"}
                propertiesOpen={layout.propertiesOpen}
                onToggleProperties={() =>
                  layout.setPropertiesOpen(!layout.propertiesOpen)
                }
                captureState={captureState}
                captureDevices={captureDevices}
                captureSelectedDevice={(source) =>
                  capture.selectedDeviceId(source)
                }
                onSelectCaptureDevice={(source, id) => {
                  capture.selectDevice(source, id);
                  // 選択は localStorage 側に持つので React state は
                  // 変わらない — ✓ を即座に反映するため再描画を起こす。
                  setCaptureDevices((d) => (d ? { ...d } : d));
                }}
                onCaptureMenuOpen={refreshCaptureDevices}
              />
              {regions.waveform ? (
                <WaveformView
                  height={layout.waveformHeight}
                  min={layout.waveformMin}
                  max={layout.waveformMax}
                  onResize={layout.requestWaveformHeight}
                  onReset={layout.resetWaveformHeight}
                  audio={importState.audio}
                  loading={screen === "openingAudio"}
                  positionSec={transportSnap?.time}
                  onSeek={(s) => {
                    void transport.seek(s).catch(() => undefined);
                  }}
                  captureState={captureState}
                  selection={
                    screen === "audioReady" &&
                    transcriptionOptions.range === "selection"
                      ? {
                          startSec: transcriptionOptions.selectionStartSec ?? 0,
                          endSec:
                            transcriptionOptions.selectionEndSec ??
                            (importState.audio?.durationSeconds ?? 0),
                        }
                      : null
                  }
                  onSelect={
                    screen === "audioReady"
                      ? (range) =>
                          setTranscriptionOptions({
                            ...transcriptionOptions,
                            range: "selection",
                            selectionStartSec: range.startSec,
                            selectionEndSec: range.endSec,
                          })
                      : undefined
                  }
                  // #113: armed media loop band + selection context
                  // actions (spec 8: ループ/再生/ズーム/解除).
                  loop={
                    transportSnap?.loop
                      ? {
                          startSec: transportSnap.loop.start,
                          endSec: transportSnap.loop.end,
                        }
                      : null
                  }
                  onLoopSelection={(range) => {
                    if (transportSnap?.loop) transport.setLoop(null);
                    else {
                      transport.setLoop({
                        start: range.startSec,
                        end: range.endSec,
                      });
                      setStatusMessage(ja.commandFeedback.loopOn);
                    }
                  }}
                  onPlaySelection={(range) => {
                    void transport
                      .playRange(range.startSec, range.endSec)
                      .catch(() => undefined);
                  }}
                  onClearSelection={() => {
                    if (transcriptionOptions.range === "selection") {
                      setTranscriptionOptions({
                        ...transcriptionOptions,
                        range: "all",
                      });
                    }
                  }}
                />
              ) : null}
              <div className="hs-main">
                <ScoreWorkspace
                  screen={screen}
                  importView={importView}
                  externalDragActive={nativeDrag}
                  onDropFiles={(files) =>
                    // 録音中のドロップは取り込み済み録音を黙って上書きする
                    // ので受け付けない(file.openAudio と同じゲート)。
                    captureState?.phase === "recording"
                      ? undefined
                      : void importer.importRefs(
                          files.map<AudioFileRef>((file) => ({
                            kind: "file",
                            file,
                            name: file.name,
                          })),
                        )
                  }
                  onTranscribe={transcribeClicked}
                  transcribingBody={
                    <TranscriptionView job={job} commands={commands} />
                  }
                  transcriptionErrorBody={
                    <TranscriptionErrorView
                      kind={sessionSnap.failure?.kind ?? "transcriptionFailed"}
                      restarting={engineRestarting}
                      diagnostics={() => session.buildDiagnostics()}
                      onPrimary={() => {
                        const failure = sessionSnap.failure;
                        if (!failure || failure.kind === "transcriptionFailed") {
                          // 再試行 is explicit — never a silent resubmit.
                          setScreen("transcribing");
                          setStatusMessage(ja.transcription.start);
                          session.clearFailure();
                          void stageAudioForEngine(importState.audio)
                            .then((staged) =>
                              session.startTranscription(
                                buildTranscriptionParams(
                                  importState.audio,
                                  transcriptionOptions,
                                  staged,
                                  settings.backend,
                                ),
                              ),
                            )
                            .catch(() => undefined);
                        } else {
                          // エンジンを再起動 — the §20 crash recovery action.
                          setEngineRestarting(true);
                          session
                            .restartEngine()
                            .then(() => {
                              session.clearFailure();
                              setScreen(hasScore ? "scoreReady" : "audioReady");
                              setStatusMessage(ja.status.engineRestarted);
                            })
                            .catch(() => {
                              /* failure stays set — surface remains */
                            })
                            .finally(() => setEngineRestarting(false));
                        }
                      }}
                      onClose={() => {
                        session.clearFailure();
                        session.clearJob();
                        setScreen(hasScore ? "scoreReady" : "audioReady");
                      }}
                    />
                  }
                  scoreDocument={scoreDocument}
                  pitch={pitch}
                  initialViewMode={settings.scoreInitialView}
                  followPlayback={settings.followPlayback}
                  onInspectorChange={setInspectorModel}
                  onScoreStateChange={setScoreState}
                  scoreControllerRef={(c) => {
                    scoreCtlRef.current = c;
                  }}
                  announce={setStatusMessage}
                  transport={
                    mediaLive && transportSnap
                      ? {
                          isPlaying: transportSnap.status === "playing",
                          positionSec: transportSnap.time,
                          rate: transportSnap.rate,
                        }
                      : null
                  }
                  sourceControl={
                    // UI-050 元音源を再生 — real audio clock when a source is
                    // loaded; the score clock covers fixture/dev playback.
                    mediaLive
                      ? {
                          seekTo: (s: number) =>
                            void transport.seek(s).catch(() => undefined),
                          play: () =>
                            void transport.play().catch(() => undefined),
                          setLoop: (r) => transport.setLoop(r),
                        }
                        : null
                  }
                  onRhythmEdit={applyRhythmEdit}
                />
                {propertiesVisible ? (
                  <PropertiesPanel
                    content={inspector}
                    model={inspectorModel}
                    pitch={pitch}
                    width={layout.propertiesWidth}
                    min={layout.propertiesMin}
                    max={layout.propertiesMax}
                    overlay={layout.breakpoint === "compact"}
                    onResize={layout.requestPropertiesWidth}
                    onReset={layout.resetPropertiesWidth}
                    onClose={closeProperties}
                    onTempoChange={(bpm) =>
                      scoreCtlRef.current?.setTempo?.(bpm)
                    }
                    onMeterChange={(b, u) =>
                      scoreCtlRef.current?.setMeter?.(b, u)
                    }
                  />
                ) : null}
              </div>
              {regions.transport ? (
                <TransportBar
                  commands={commands}
                  live={
                    transportSnap && transportSnap.status !== "empty"
                      ? {
                          isPlaying: transportSnap.status === "playing",
                          positionSec: transportSnap.time,
                          durationSec: transportSnap.duration,
                          rate: transportSnap.rate,
                          muted: transportSnap.muted,
                        }
                      : undefined
                  }
                  onCycleRate={() => {
                    const idx = SUPPORTED_RATES.findIndex(
                      (r) => r === transportSnap?.rate,
                    );
                    const next =
                      SUPPORTED_RATES[(idx + 1) % SUPPORTED_RATES.length] ?? 1;
                    transport.setRate(next);
                  }}
                  timeLabel={
                    !mediaLive && scoreState
                      ? `${formatScoreTimecode(scoreState.positionMs)} / ${formatScoreTimecode(scoreState.durationMs)}`
                      : undefined
                  }
                  followEnabled={scoreState?.followEnabled}
                  followSuspended={scoreState?.followSuspended}
                  onToggleFollow={() => {
                    const c = scoreCtlRef.current;
                    if (!c) return;
                    if (scoreState?.followSuspended) c.resumeFollow();
                    else c.setFollowEnabled(!(scoreState?.followEnabled ?? true));
                  }}
                  auditionEnabled={scoreState?.auditionEnabled}
                  loopArmed={
                    transportSnap?.loop != null ||
                    (scoreState?.loopEnabled ?? false)
                  }
                />
              ) : null}
            </>
          )}
          <StatusBar
            message={statusMessage}
            detail={shellDetail}
            engineStatus={engineStatusText(sessionSnap.engine)}
          />
          {/* Re-import failure over a live workspace (§20): the audio session
              is kept, the failure surfaces as a dialog — never a dead end. */}
          {/* #76: 録音は現在の音源(と楽譜)を置き換えるため、開始前に確認。
              alert 型 = 破壊的操作の確認(JAPANESE_UI_COPY §8)。 */}
          <HsDialog
            open={pendingCapture !== null}
            modalType="alert"
            title={ja.capture.replaceTitle}
            onOpenChange={(open) => {
              if (!open) setPendingCapture(null);
            }}
            actions={
              <>
                <HsButton variant="danger" onClick={confirmCapture}>
                  {ja.capture.replaceConfirm}
                </HsButton>
                <HsButton
                  variant="secondary"
                  onClick={() => setPendingCapture(null)}
                >
                  {ja.capture.replaceCancel}
                </HsButton>
              </>
            }
          >
            <p style={{ margin: 0 }}>
              {scoreDocument
                ? ja.capture.replaceBodyWithScore
                : ja.capture.replaceBody}
            </p>
          </HsDialog>
          {importState.audio && importState.issue
            ? (() => {
                const copy = issueCopy(importState.issue);
                return (
                  <HsDialog
                    open
                    title={copy.title}
                    onOpenChange={(open) => {
                      if (!open) importer.dismiss();
                    }}
                    actions={
                      <>
                        <HsButton
                          variant="primary"
                          onClick={() => {
                            importer.dismiss();
                            void importer.openViaDialog();
                          }}
                        >
                          {ja.import.errors.chooseAnother}
                        </HsButton>
                        <HsButton
                          variant="secondary"
                          onClick={() => importer.dismiss()}
                        >
                          {ja.import.errors.close}
                        </HsButton>
                      </>
                    }
                  >
                    <p style={{ margin: 0 }}>
                      {copy.fileName ? `${copy.fileName} — ` : ""}
                      {copy.body}
                    </p>
                  </HsDialog>
                );
              })()
            : null}
          {/* UI-060 secondary surfaces — modals over the shell, never a
              workspace mode. Recovery paths deep-link into 設定/診断情報. */}
          <ExportDialog
            open={exportOpen}
            onOpenChange={setExportOpen}
            port={exportPort}
            defaultDestination={settings.defaultExportDir}
            toolOverrides={toolOverrides}
            onOpenSettings={(category) => {
              setSettingsFocus(category);
              setView("settings");
            }}
            onOpenDiagnostics={() => setDiagnosticsOpen(true)}
            onAnnounce={setStatusMessage}
          />
          <DiagnosticsSheet
            open={diagnosticsOpen}
            onOpenChange={setDiagnosticsOpen}
            port={diagnosticsPort}
            toolOverrides={toolOverrides}
            onAnnounce={setStatusMessage}
          />
          {/* #130 (spec 14): quantization settings on the finished
              score — seeded from the canonical payload's stored
              quantizationSettings; apply goes through the undoable
              score.edit path on the workspace controller. */}
          <RequantizeDialog
            open={requantizeOpen}
            seed={
              requantizeOpen
                ? requantizeSeed(scoreDocument?.canonicalDocument?.())
                : null
            }
            onOpenChange={setRequantizeOpen}
            onApply={(overrides) =>
              scoreCtlRef.current?.requantize?.(overrides)
            }
          />
        </AppShell>
      )}
    </FluentProvider>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { Tooltip } from "@fluentui/react-components";
import {
  ArrowRepeatAll24Regular,
  Play24Regular,
  ZoomIn24Regular,
  Dismiss24Regular,
  ZoomFit24Regular,
} from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import {
  readWaveformView,
  resizeKeyDelta,
  startPointerResize,
  writeWaveformView,
} from "../workspace/layout";
import type { LoadedAudio } from "../import/types";
import type { CaptureState } from "../capture/controller";
import { formatTimecode } from "../import/format";
import {
  centerViewAt,
  clientXInView,
  clientXToSeconds,
  clampView,
  DRAG_THRESHOLD_PX,
  fullView,
  isFullView,
  normalizeSelection,
  panView,
  selectionBandInView,
  zoomView,
  type SelectionRange,
  type ViewRange,
} from "../import/selection";

/** #116 (spec 8): the minimap strip appears for long clips (>=5 min) or
 *  whenever the view is zoomed — short full-view clips don't need it. */
const MINIMAP_MIN_DURATION_SEC = 300;
/** Peaks columns in the minimap — fixed, so the strip stays cheap. */
const MINIMAP_COLUMNS = 160;

/** Downsample peaks to `columns` max-per-bucket values for the minimap. */
function minimapPeaks(
  peaks: readonly number[],
  columns: number,
): readonly number[] {
  if (peaks.length <= columns) return peaks;
  const out: number[] = new Array(columns).fill(0);
  const bucket = peaks.length / columns;
  for (let i = 0; i < columns; i++) {
    const lo = Math.floor(i * bucket);
    const hi = Math.min(
      peaks.length,
      Math.max(lo + 1, Math.ceil((i + 1) * bucket)),
    );
    let m = 0;
    for (let j = lo; j < hi; j++) if (peaks[j] > m) m = peaks[j];
    out[i] = m;
  }
  return out;
}

/** Peak-column path for the strip: one <path> keeps redraw cost flat -
 *  vertical bars centred on the midline. `peaks` is the slice currently
 *  inside the zoom window.
 */
function peaksPath(peaks: readonly number[]): string {
  let d = "";
  for (let i = 0; i < peaks.length; i++) {
    const p = Math.min(1, Math.max(0, peaks[i]));
    d += `M${i + 0.5} ${50 - p * 48}L${i + 0.5} ${50 + p * 48}`;
  }
  return d;
}

/** Slice the peaks array to the visible window so zooming redraws the
 *  same columns at a wider pitch (spec 8: Ctrl+wheel zoom). */
function peaksInView(
  peaks: readonly number[],
  view: ViewRange,
  durationSec: number,
): readonly number[] {
  if (durationSec <= 0 || peaks.length === 0) return peaks;
  const lo = Math.max(0, Math.floor((view.startSec / durationSec) * peaks.length));
  const hi = Math.min(
    peaks.length,
    Math.max(lo + 1, Math.ceil((view.endSec / durationSec) * peaks.length)),
  );
  return peaks.slice(lo, hi);
}

/**
 * Waveform / timeline region (GUI_UX_SPEC 2, 8).
 * Height is user-resizable: 64px minimum up to ~35% of the work area, and
 * always smaller than the score. The bottom-edge separator supports pointer
 * drag, ArrowUp/ArrowDown (±8px) and double-click reset - deterministic
 * clamps live in workspace/layout.ts.
 *
 * UI-020: renders decoded peaks + playhead once audio loads (spec 4), the
 * loading line while OPENING_AUDIO, and click-to-seek
 * (spec 8) against the transport clock.
 *
 * #88: when `onSelect` is provided (AUDIO_READY), a horizontal drag past
 * DRAG_THRESHOLD_PX commits a selection range instead of seeking - the
 * committed band plus live drag preview paint over the peaks. A plain
 * click still seeks so the user can audition the range edges.
 *
 * #113 (spec 8): the committed selection carries edge handles and a
 * context action bar (loop / play / zoom / clear); Esc clears it.
 * Ctrl+wheel zooms the visible window around the cursor and a plain wheel
 * pans it once zoomed; the zoom chip resets to the whole clip. The armed
 * A-B loop paints as a second band (`loop` prop).
*/
export function WaveformView({
  height,
  min,
  max,
  onResize,
  onReset,
  audio,
  loading = false,
  positionSec,
  onSeek,
  captureState,
  selection,
  onSelect,
  loop,
  onLoopSelection,
  onPlaySelection,
  onClearSelection,
}: {
  height: number;
  min: number;
  max: number;
  onResize(px: number): void;
  onReset(): void;
  /** Decoded audio (UI-020) - peaks render, null keeps the placeholder. */
  audio?: Pick<
    LoadedAudio,
    "fileName" | "durationSeconds" | "peaks"
  > | null;
  /** OPENING_AUDIO - honest loading line instead of fake peaks. */
  loading?: boolean;
  /** Audio-clock position for the playhead (seconds). */
  positionSec?: number;
  /** spec 8 click -> seek: receives the target time in seconds. */
  onSeek?(seconds: number): void;
  /** FEAT-001 (#60): recording state - while a capture runs the strip
   *  shows the live recording status instead of a file's peaks. */
  captureState?: CaptureState | null;
  /** #88: committed selection (seconds) - renders the band when set. */
  selection?: SelectionRange | null;
  /** #88: drag-to-select - when absent the strip stays seek-only. */
  onSelect?(range: SelectionRange): void;
  /** #113: armed media A-B loop (seconds) - painted as a second band. */
  loop?: SelectionRange | null;
  /** #113: context action - arm/clear the A-B loop on this range. */
  onLoopSelection?(range: SelectionRange): void;
  /** #113: context action - play [start, end) once, then pause. */
  onPlaySelection?(range: SelectionRange): void;
  /** #113: context action / Esc - drop the committed selection. */
  onClearSelection?(): void;
}) {
  const duration = audio?.durationSeconds ?? 0;

  // spec 15: the zoom window lives inside the strip - it resets whenever a
  // different clip loads (identity change), never mid-gesture.
  const [view, setView] = useState<ViewRange>(() => fullView(duration));
  const audioRef = useRef(audio);
  if (audioRef.current !== audio) {
    audioRef.current = audio;
    // §26 session restore: reopening the same clip brings back the
    // zoomed window the user left; a different clip starts full.
    const restored =
      audio != null
        ? readWaveformView(audio.fileName, audio.durationSeconds)
        : null;
    setView(restored ?? fullView(duration));
  }

  // Persist the zoom window per source (debounced — wheel zooms fire in
  // bursts). A full view clears the stored entry so a re-open starts
  // full instead of restoring a stale window.
  useEffect(() => {
    if (audio == null || duration <= 0) return;
    const fileName = audio.fileName;
    const durationSeconds = audio.durationSeconds;
    const timer = window.setTimeout(() => {
      writeWaveformView(
        fileName,
        durationSeconds,
        isFullView(view, durationSeconds) ? null : view,
      );
    }, 300);
    return () => window.clearTimeout(timer);
  }, [audio, view, duration]);

  const rootRef = useRef<HTMLDivElement | null>(null);
  const viewRef = useRef(view);
  viewRef.current = view;
  const durationRef = useRef(duration);
  durationRef.current = duration;

  // Ctrl+wheel zoom / wheel pan need preventDefault, so the listener is
  // attached non-passively (React registers wheel handlers as passive).
  useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const onWheel = (e: WheelEvent) => {
      const dur = durationRef.current;
      if (dur <= 0) return;
      const rect = el.getBoundingClientRect();
      if (e.ctrlKey || e.metaKey) {
        e.preventDefault();
        const anchor = clientXInView(e.clientX, rect.left, rect.width, viewRef.current);
        const factor = e.deltaY < 0 ? 0.8 : 1.25;
        setView(zoomView(viewRef.current, anchor, factor, dur));
        return;
      }
      if (isFullView(viewRef.current, dur)) return;
      e.preventDefault();
      const span = viewRef.current.endSec - viewRef.current.startSec;
      const deltaPx = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;
      setView(panView(viewRef.current, (deltaPx / Math.max(1, rect.width)) * span, dur));
    };
    el.addEventListener("wheel", onWheel, { passive: false });
    return () => el.removeEventListener("wheel", onWheel);
  }, []);

  const visiblePeaks = useMemo(
    () => (audio ? peaksInView(audio.peaks, view, duration) : []),
    [audio, view, duration],
  );
  const path = useMemo(() => peaksPath(visiblePeaks), [visiblePeaks]);

  const span = view.endSec - view.startSec;
  const ratio =
    positionSec != null && span > 0 &&
    positionSec >= view.startSec && positionSec <= view.endSec
      ? Math.min(1, Math.max(0, (positionSec - view.startSec) / span))
      : null;

  // #88: drag gesture - a press+release under DRAG_THRESHOLD_PX stays a
  // click (seek); past it the gesture becomes a range selection.
  const [dragRange, setDragRange] = useState<SelectionRange | null>(null);
  const gesture = useRef<{
    pointerId: number;
    startX: number;
    startSec: number;
    rect: DOMRect;
    dragging: boolean;
  } | null>(null);

  const onPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!audio || duration <= 0 || e.button !== 0) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const g = {
      pointerId: e.pointerId,
      startX: e.clientX,
      startSec: clientXInView(e.clientX, rect.left, rect.width, viewRef.current),
      rect,
      dragging: false,
    };
    gesture.current = g;
    const move = (ev: PointerEvent) => {
      if (gesture.current !== g || ev.pointerId !== g.pointerId) return;
      if (!g.dragging) {
        if (Math.abs(ev.clientX - g.startX) < DRAG_THRESHOLD_PX) return;
        if (!onSelect) return; // seek-only strip: drags do nothing
        g.dragging = true;
      }
      const sec = clientXInView(
        ev.clientX,
        g.rect.left,
        g.rect.width,
        viewRef.current,
      );
      setDragRange(normalizeSelection(g.startSec, sec, duration));
    };
    const finish = (commit: boolean) => (ev: PointerEvent) => {
      if (gesture.current !== g || ev.pointerId !== g.pointerId) return;
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onCancel);
      gesture.current = null;
      if (g.dragging) {
        setDragRange(null);
        if (commit && onSelect) {
          const sec = clientXInView(
            ev.clientX,
            g.rect.left,
            g.rect.width,
            viewRef.current,
          );
          onSelect(normalizeSelection(g.startSec, sec, duration));
        }
      } else if (commit && onSeek) {
        onSeek(g.startSec);
      }
    };
    const onUp = finish(true);
    const onCancel = finish(false);
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onCancel);
  };

  // #113: edge handles on the committed band - dragging one edge keeps the
  // other anchored and re-commits through onSelect.
  const onHandleDown = (edge: "start" | "end") =>
    (e: React.PointerEvent<HTMLDivElement>) => {
      if (!selection || !onSelect || e.button !== 0) return;
      e.stopPropagation();
      const rect = rootRef.current?.getBoundingClientRect();
      if (!rect) return;
      const pointerId = e.pointerId;
      const move = (ev: PointerEvent) => {
        if (ev.pointerId !== pointerId) return;
        const sec = clientXInView(ev.clientX, rect.left, rect.width, viewRef.current);
        const next =
          edge === "start"
            ? normalizeSelection(sec, selection.endSec, duration)
            : normalizeSelection(selection.startSec, sec, duration);
        onSelect(next);
      };
      const up = (ev: PointerEvent) => {
        if (ev.pointerId !== pointerId) return;
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", up);
        window.removeEventListener("pointercancel", up);
      };
      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", up);
      window.addEventListener("pointercancel", up);
    };

  const liveBand = selectionBandInView(dragRange, view);
  const committedBand = selectionBandInView(selection ?? null, view);
  const band = liveBand ?? committedBand;
  const bandRange = dragRange ?? selection ?? null;
  const loopBand = selectionBandInView(loop ?? null, view);
  const zoomed = !isFullView(view, duration);

  const clearCommitted = () => {
    onClearSelection?.();
  };

  // #116 (spec 8): minimap — long clips (>=5 min) or any zoomed view.
  // Click/drag centres the zoom window (or seeks when zoomed out);
  // arrow keys do the same for keyboard users.
  const showMinimap =
    audio != null &&
    duration > 0 &&
    (duration >= MINIMAP_MIN_DURATION_SEC || zoomed);
  const miniPeaks = useMemo(
    () => (audio ? minimapPeaks(audio.peaks, MINIMAP_COLUMNS) : []),
    [audio],
  );
  const miniPath = useMemo(() => peaksPath(miniPeaks), [miniPeaks]);
  const miniViewBand =
    zoomed && duration > 0
      ? { left: view.startSec / duration, width: span / duration }
      : null;
  const miniPlayheadRatio =
    positionSec != null && duration > 0
      ? Math.min(1, Math.max(0, positionSec / duration))
      : null;

  const onMinimapDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!audio || duration <= 0 || e.button !== 0) return;
    e.stopPropagation();
    const rect = e.currentTarget.getBoundingClientRect();
    const pointerId = e.pointerId;
    const apply = (clientX: number) => {
      const sec = clientXToSeconds(clientX, rect.left, rect.width, duration);
      if (isFullView(viewRef.current, duration)) onSeek?.(sec);
      else setView(centerViewAt(viewRef.current, sec, duration));
    };
    apply(e.clientX);
    const move = (ev: PointerEvent) => {
      if (ev.pointerId === pointerId) apply(ev.clientX);
    };
    const up = (ev: PointerEvent) => {
      if (ev.pointerId !== pointerId) return;
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
      window.removeEventListener("pointercancel", up);
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
    window.addEventListener("pointercancel", up);
  };

  const onMinimapKey = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (!audio || duration <= 0) return;
    const step = Math.max(1, duration * 0.05);
    const v = viewRef.current;
    const zoomedNow = !isFullView(v, duration);
    const moveView = (deltaSec: number) =>
      setView(panView(v, deltaSec, duration));
    const movePlayhead = (sec: number) => {
      const clamped = Math.min(Math.max(sec, 0), duration);
      if (zoomedNow) setView(centerViewAt(v, clamped, duration));
      else onSeek?.(clamped);
    };
    switch (e.key) {
      case "ArrowLeft":
        e.preventDefault();
        e.stopPropagation();
        if (zoomedNow) moveView(-step);
        else movePlayhead((positionSec ?? 0) - step);
        break;
      case "ArrowRight":
        e.preventDefault();
        e.stopPropagation();
        if (zoomedNow) moveView(step);
        else movePlayhead((positionSec ?? 0) + step);
        break;
      case "PageUp":
        e.preventDefault();
        e.stopPropagation();
        if (zoomedNow) moveView(-step * 4);
        else movePlayhead((positionSec ?? 0) - step * 4);
        break;
      case "PageDown":
        e.preventDefault();
        e.stopPropagation();
        if (zoomedNow) moveView(step * 4);
        else movePlayhead((positionSec ?? 0) + step * 4);
        break;
      case "Home":
        e.preventDefault();
        e.stopPropagation();
        movePlayhead(0);
        break;
      case "End":
        e.preventDefault();
        e.stopPropagation();
        movePlayhead(duration);
        break;
    }
  };

  return (
    <div
      ref={rootRef}
      className={[
        "hs-waveform",
        onSelect ? "hs-waveform--selectable" : null,
        showMinimap ? "hs-waveform--minimap" : null,
      ]
        .filter(Boolean)
        .join(" ")}
      role="region"
      aria-label={ja.waveform.regionLabel}
      data-hs-focus-zone="waveform"
      tabIndex={0}
      style={{ height }}
      onPointerDown={onPointerDown}
      onKeyDown={(e) => {
        // spec 8: Esc clears the committed selection first, then zoom.
        if (e.key !== "Escape") return;
        if (selection) {
          e.stopPropagation();
          clearCommitted();
        } else if (zoomed) {
          e.stopPropagation();
          setView(fullView(duration));
        }
      }}
    >
      {loading ? (
        <span className="hs-waveform__placeholder">
          {ja.import.waveform.loading}
        </span>
      ) : captureState?.phase === "recording" ? (
        <span
          className="hs-waveform__recording"
          role="status"
          aria-live="polite"
        >
          {captureState.source === "loopback"
            ? ja.transport.recordingLoopbackLabel
            : ja.transport.recordingLabel}
          {" - "}
          {formatTimecode(captureState.elapsedSeconds)}
          {captureState.deviceName ? ` · ${captureState.deviceName}` : ""}
          {/* #71: 入力レベルの簡易メーター(0-1 のピーク)。 */}
          <span
            className="hs-waveform__level"
            aria-hidden="true"
          >
            <span
              className="hs-waveform__level-fill"
              style={{
                width: `${Math.round(
                  Math.min(1, Math.max(0, captureState.level ?? 0)) * 100,
                )}%`,
              }}
            />
          </span>
        </span>
      ) : audio ? (
        <>
          <svg
            className="hs-waveform__peaks"
            viewBox={`0 0 ${Math.max(1, visiblePeaks.length)} 100`}
            preserveAspectRatio="none"
            aria-hidden="true"
          >
            <path d={path} />
          </svg>
          {loopBand ? (
            <div
              className="hs-waveform__loop"
              style={{
                left: loopBand.left * 100 + "%",
                width: loopBand.width * 100 + "%",
              }}
              aria-hidden="true"
            />
          ) : null}
          {band ? (
            <div
              className={liveBand
                ? "hs-waveform__selection hs-waveform__selection--live"
                : "hs-waveform__selection"}
              style={{
                left: band.left * 100 + "%",
                width: band.width * 100 + "%",
              }}
              aria-hidden="true"
            >
              {bandRange ? (
                <span className="hs-waveform__selection-label">
                  {formatTimecode(bandRange.startSec)}
                  {" - "}
                  {formatTimecode(bandRange.endSec)}
                </span>
              ) : null}
            </div>
          ) : null}
          {/* #113: edge handles on the committed band only - the live
              preview is already following the pointer. */}
          {committedBand && !liveBand && onSelect ? (
            <>
              <div
                className="hs-waveform__handle hs-waveform__handle--start"
                style={{ left: `calc(${committedBand.left * 100}% - 4px)` }}
                onPointerDown={onHandleDown("start")}
              />
              <div
                className="hs-waveform__handle hs-waveform__handle--end"
                style={{
                  left: `calc(${(committedBand.left + committedBand.width) * 100}% - 4px)`,
                }}
                onPointerDown={onHandleDown("end")}
              />
            </>
          ) : null}
          {ratio !== null ? (
            <div
              className="hs-waveform__playhead"
              style={{ left: `${ratio * 100}%` }}
              aria-hidden="true"
            />
          ) : null}
          <span className="hs-waveform__name" aria-hidden="true">
            {audio.fileName}
          </span>
          {/* #113: context actions for the committed selection (spec 8). */}
          {committedBand && !liveBand ? (
            <div
              className="hs-waveform__actions"
              role="toolbar"
              aria-label={ja.waveform.selectionActions}
              style={{
                left: `${Math.min(
                  96,
                  (committedBand.left + committedBand.width) * 100,
                )}%`,
              }}
              onPointerDown={(e) => e.stopPropagation()}
            >
              <Tooltip content={ja.waveform.loopSelection} relationship="label">
                <button
                  type="button"
                  className="hs-waveform__action"
                  aria-label={ja.waveform.loopSelection}
                  onClick={() =>
                    selection && onLoopSelection?.(selection)
                  }
                >
                  <ArrowRepeatAll24Regular />
                </button>
              </Tooltip>
              <Tooltip content={ja.waveform.playSelection} relationship="label">
                <button
                  type="button"
                  className="hs-waveform__action"
                  aria-label={ja.waveform.playSelection}
                  onClick={() =>
                    selection && onPlaySelection?.(selection)
                  }
                >
                  <Play24Regular />
                </button>
              </Tooltip>
              <Tooltip content={ja.waveform.zoomSelection} relationship="label">
                <button
                  type="button"
                  className="hs-waveform__action"
                  aria-label={ja.waveform.zoomSelection}
                  onClick={() =>
                    selection &&
                    setView(clampView(selection, duration))
                  }
                >
                  <ZoomIn24Regular />
                </button>
              </Tooltip>
              <Tooltip content={ja.waveform.clearSelection} relationship="label">
                <button
                  type="button"
                  className="hs-waveform__action"
                  aria-label={ja.waveform.clearSelection}
                  onClick={clearCommitted}
                >
                  <Dismiss24Regular />
                </button>
              </Tooltip>
            </div>
          ) : null}
          {/* #113: zoomed-state chip - one click back to the whole clip. */}
          {zoomed ? (
            <Tooltip content={ja.waveform.resetZoom} relationship="label">
              <button
                type="button"
                className="hs-waveform__zoom-reset"
                aria-label={ja.waveform.resetZoom}
                onClick={() => setView(fullView(duration))}
                onPointerDown={(e) => e.stopPropagation()}
              >
                <ZoomFit24Regular />
                <span>{ja.waveform.zoomedLabel}</span>
              </button>
            </Tooltip>
          ) : null}
        </>
      ) : (
        <span className="hs-waveform__placeholder">
          {ja.waveform.placeholder}
        </span>
      )}
      {/* #116 (spec 8): minimap — whole-clip strip with the zoom window
          as a band; click/drag/keys navigate. Long clips or zoomed only. */}
      {showMinimap ? (
        <div
          className="hs-waveform__minimap"
          role="slider"
          aria-label={ja.waveform.minimap}
          aria-orientation="horizontal"
          aria-valuemin={0}
          aria-valuemax={Math.round(duration)}
          aria-valuenow={Math.round(
            zoomed ? view.startSec : (positionSec ?? 0),
          )}
          aria-valuetext={formatTimecode(
            zoomed ? view.startSec : (positionSec ?? 0),
          )}
          tabIndex={0}
          onPointerDown={onMinimapDown}
          onKeyDown={onMinimapKey}
        >
          <svg
            className="hs-waveform__minimap-peaks"
            viewBox={`0 0 ${Math.max(1, miniPeaks.length)} 100`}
            preserveAspectRatio="none"
            aria-hidden="true"
          >
            <path d={miniPath} />
          </svg>
          {miniViewBand ? (
            <div
              className="hs-waveform__minimap-window"
              style={{
                left: `${miniViewBand.left * 100}%`,
                width: `${Math.max(0.5, miniViewBand.width * 100)}%`,
              }}
              aria-hidden="true"
            />
          ) : null}
          {miniPlayheadRatio !== null ? (
            <div
              className="hs-waveform__minimap-playhead"
              style={{ left: `${miniPlayheadRatio * 100}%` }}
              aria-hidden="true"
            />
          ) : null}
        </div>
      ) : null}
      <div
        className="hs-waveform__resizer"
        role="separator"
        aria-orientation="horizontal"
        aria-label={ja.waveform.resizeHandle}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={height}
        tabIndex={0}
        onPointerDown={(e) => {
          // Keep the resize gesture out of the strip's select/seek
          // pointerdown (it bubbles up to .hs-waveform otherwise).
          e.stopPropagation();
          const startH = height;
          const startY = e.clientY;
          startPointerResize(e, onResize, (_x, y) => startH + (y - startY));
        }}
        onClick={(e) => e.stopPropagation()}
        onKeyDown={(e) => {
          const next = resizeKeyDelta(e, height);
          if (next != null) {
            e.preventDefault();
            onResize(next);
          }
        }}
        onDoubleClick={onReset}
      />
    </div>
  );
}

// @vitest-environment jsdom
import { beforeEach, describe, expect, it } from "vitest";
import {
  readWaveformView,
  readScoreSessionView,
  writeWaveformView,
  writeScoreSessionView,
} from "./layout";

/* §26: score view session restore — zoom % and view mode persist in
 * the shared layout record. */

const KEY = "hornscribe.layout.v1";

beforeEach(() => {
  window.localStorage.clear();
});

describe("score session view", () => {
  it("returns nulls when nothing is stored", () => {
    expect(readScoreSessionView()).toEqual({
      zoomPct: null,
      viewMode: null,
    });
  });

  it("round-trips zoom and view mode", () => {
    writeScoreSessionView({ zoomPct: 150 });
    writeScoreSessionView({ viewMode: "page" });
    expect(readScoreSessionView()).toEqual({
      zoomPct: 150,
      viewMode: "page",
    });
  });

  it("preserves other layout fields", () => {
    window.localStorage.setItem(
      KEY,
      JSON.stringify({ propertiesWidth: 320, propertiesOpen: true }),
    );
    writeScoreSessionView({ zoomPct: 75 });
    const raw = JSON.parse(window.localStorage.getItem(KEY) ?? "{}");
    expect(raw.propertiesWidth).toBe(320);
    expect(raw.propertiesOpen).toBe(true);
    expect(raw.scoreZoomPct).toBe(75);
  });

  it("ignores corrupt/foreign values", () => {
    window.localStorage.setItem(
      KEY,
      JSON.stringify({ scoreZoomPct: "wide", scoreViewMode: "grid" }),
    );
    expect(readScoreSessionView()).toEqual({
      zoomPct: null,
      viewMode: null,
    });
    window.localStorage.setItem(KEY, "not json");
    expect(readScoreSessionView()).toEqual({
      zoomPct: null,
      viewMode: null,
    });
  });
});

describe("waveform view persistence", () => {
  it("returns null when nothing is stored", () => {
    expect(readWaveformView("take.wav", 120)).toBeNull();
  });

  it("round-trips a zoom window per source", () => {
    writeWaveformView("take.wav", 120, { startSec: 10, endSec: 30 });
    expect(readWaveformView("take.wav", 120)).toEqual({
      startSec: 10,
      endSec: 30,
    });
    // A different clip does not inherit the window.
    expect(readWaveformView("other.wav", 120)).toBeNull();
    expect(readWaveformView("take.wav", 60)).toBeNull();
  });

  it("clears the entry on a full view", () => {
    writeWaveformView("take.wav", 120, { startSec: 10, endSec: 30 });
    writeWaveformView("take.wav", 120, null);
    expect(readWaveformView("take.wav", 120)).toBeNull();
  });

  it("rejects ranges outside the clip", () => {
    writeWaveformView("take.wav", 120, { startSec: 10, endSec: 30 });
    // Same file name, shorter clip -> stored window no longer fits.
    expect(readWaveformView("take.wav", 15)).toBeNull();
  });

  it("clamps the end to the clip duration", () => {
    window.localStorage.setItem(
      KEY,
      JSON.stringify({
        waveformViews: { "take.wav|120.000": { startSec: 10, endSec: 200 } },
      }),
    );
    expect(readWaveformView("take.wav", 120)).toEqual({
      startSec: 10,
      endSec: 120,
    });
  });

  it("caps stored clips and keeps the freshest", () => {
    for (let i = 0; i < 20; i += 1) {
      writeWaveformView("clip-" + i + ".wav", 60, { startSec: 1, endSec: 2 });
    }
    const raw = JSON.parse(window.localStorage.getItem(KEY) ?? "{}");
    expect(Object.keys(raw.waveformViews)).toHaveLength(16);
    expect(readWaveformView("clip-19.wav", 60)).not.toBeNull();
    expect(readWaveformView("clip-0.wav", 60)).toBeNull();
  });
});

import { useCallback, useEffect, useState } from "react";

/**
 * Workspace layout state (docs/GUI_UX_SPEC.md §21 responsive, §26 session
 * restore).
 *
 * Breakpoints (window inner width, CSS px):
 *   >=1600  wide     properties docked 280–320px, full command labels
 *   1200–1599 medium  properties docked 240–280px, secondary labels icon化
 *   1100–1199 compact properties becomes an overlay drawer, less-frequent
 *                    commands move to overflow; score keeps priority
 *   <1100   not supported — the native window minimum (1100px) stops resize
 *           before this; the CSS min-width mirrors it as a deterministic
 *           floor so the layout can never compress below the spec.
 *
 * All resize math is clamp-based and deterministic: the stored value is the
 * user's *requested* size, the rendered size is always `clamp(requested,
 * breakpointRange)` — crossing a breakpoint re-clamps without losing the
 * request.
 */
export type LayoutBreakpoint = "wide" | "medium" | "compact";

export function breakpointForWidth(width: number): LayoutBreakpoint {
  if (width >= 1600) return "wide";
  if (width >= 1200) return "medium";
  return "compact";
}

/** Docked/overlay width limits per breakpoint (§21). */
export function propertiesRange(bp: LayoutBreakpoint): {
  min: number;
  max: number;
  fallback: number;
} {
  switch (bp) {
    case "wide":
      return { min: 280, max: 320, fallback: 296 };
    case "medium":
      return { min: 240, max: 280, fallback: 264 };
    case "compact":
      // Overlay drawer: §21 gives no explicit band; keep the same order of
      // magnitude so the drawer never dwarfs the score it floats over.
      return { min: 240, max: 320, fallback: 280 };
  }
}

export function clampPropertiesWidth(
  requested: number,
  bp: LayoutBreakpoint,
): number {
  const { min, max } = propertiesRange(bp);
  return Math.min(max, Math.max(min, Math.round(requested)));
}

/* Waveform vertical band (§8): standard 96–120, min 64, max ≈35% of the
   work area (waveform + score region height). The work area is the window
   minus fixed chrome rows (title 32 + command bar 44 + transport 52 +
   status 26 = 154). */
export const WAVEFORM_DEFAULT = 96;
export const WAVEFORM_MIN = 64;
export const WORKSPACE_CHROME_HEIGHT = 154;

export function waveformMaxHeight(windowHeight: number): number {
  return Math.max(
    WAVEFORM_MIN,
    Math.round((windowHeight - WORKSPACE_CHROME_HEIGHT) * 0.35),
  );
}

export function clampWaveformHeight(
  requested: number,
  windowHeight: number,
): number {
  return Math.min(
    waveformMaxHeight(windowHeight),
    Math.max(WAVEFORM_MIN, Math.round(requested)),
  );
}

/* ----------------------------- persistence ----------------------------- */

const STORAGE_KEY = "hornscribe.layout.v1";

interface PersistedLayout {
  propertiesOpen?: boolean;
  propertiesWidth?: number;
  waveformHeight?: number;
  /** §26 session restore: last score zoom (%) and view mode. */
  scoreZoomPct?: number;
  scoreViewMode?: "continuous" | "page";
  /** §26: per-source waveform zoom windows, keyed by clip identity. */
  waveformViews?: Record<string, { startSec: number; endSec: number }>;
}

function loadLayout(): PersistedLayout {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as PersistedLayout;
    return typeof parsed === "object" && parsed !== null ? parsed : {};
  } catch {
    return {};
  }
}

function saveLayout(layout: PersistedLayout): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(layout));
  } catch {
    /* persistence is best-effort */
  }
}

/* §26: per-session score view state, restored on the next launch.
 * Read/write goes through the same layout record so panel sizes and
 * view state never clobber each other. */
export interface ScoreSessionView {
  readonly zoomPct: number | null;
  readonly viewMode: "continuous" | "page" | null;
}

export function readScoreSessionView(): ScoreSessionView {
  const stored = loadLayout();
  const zoomPct =
    typeof stored.scoreZoomPct === "number" &&
    Number.isFinite(stored.scoreZoomPct)
      ? stored.scoreZoomPct
      : null;
  const viewMode =
    stored.scoreViewMode === "continuous" || stored.scoreViewMode === "page"
      ? stored.scoreViewMode
      : null;
  return { zoomPct, viewMode };
}

export function writeScoreSessionView(patch: {
  zoomPct?: number;
  viewMode?: "continuous" | "page";
}): void {
  const next = { ...loadLayout() };
  if (patch.zoomPct !== undefined) next.scoreZoomPct = patch.zoomPct;
  if (patch.viewMode !== undefined) next.scoreViewMode = patch.viewMode;
  saveLayout(next);
}

/* §26 waveform zoom: the view window is per-source — reopening the same
 * clip restores where the user was looking, a different clip starts
 * full. Identity is fileName + duration (what the audio payload carries);
 * entries are capped LRU-ish so a busy library cannot grow the record. */
const MAX_WAVEFORM_VIEWS = 16;

function waveformViewKey(fileName: string, durationSec: number): string {
  return fileName + "|" + durationSec.toFixed(3);
}

export function readWaveformView(
  fileName: string,
  durationSec: number,
): { startSec: number; endSec: number } | null {
  const stored = loadLayout().waveformViews?.[
    waveformViewKey(fileName, durationSec)
  ];
  if (
    !stored ||
    !Number.isFinite(stored.startSec) ||
    !Number.isFinite(stored.endSec) ||
    stored.endSec <= stored.startSec ||
    stored.startSec < 0 ||
    stored.startSec >= durationSec
  ) {
    return null;
  }
  return {
    startSec: stored.startSec,
    endSec: Math.min(stored.endSec, durationSec),
  };
}

export function writeWaveformView(
  fileName: string,
  durationSec: number,
  view: { startSec: number; endSec: number } | null,
): void {
  const next = { ...loadLayout() };
  const views = { ...(next.waveformViews ?? {}) };
  const key = waveformViewKey(fileName, durationSec);
  if (view === null) {
    delete views[key];
  } else {
    // Delete-then-set moves an existing key to the end so the cap
    // evicts the least-recently-touched clip, not a hot one.
    delete views[key];
    views[key] = { startSec: view.startSec, endSec: view.endSec };
    // Evict the oldest entries past the cap (insertion order — the
    // just-written key is last, so the front is the stalest).
    const keys = Object.keys(views);
    if (keys.length > MAX_WAVEFORM_VIEWS) {
      for (const stale of keys.slice(0, keys.length - MAX_WAVEFORM_VIEWS)) {
        delete views[stale];
      }
    }
  }
  next.waveformViews = views;
  saveLayout(next);
}

/* ------------------------------- hooks -------------------------------- */

function useViewportSize(): { width: number; height: number } {
  const [size, setSize] = useState(() => ({
    width: window.innerWidth,
    height: window.innerHeight,
  }));
  useEffect(() => {
    const onResize = () =>
      setSize({ width: window.innerWidth, height: window.innerHeight });
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);
  return size;
}

export interface WorkspaceLayout {
  breakpoint: LayoutBreakpoint;
  /** Whether the properties panel is rendered (§6: user-closable). */
  propertiesOpen: boolean;
  /** Effective (clamped) docked/overlay panel width in px. */
  propertiesWidth: number;
  /** Effective (clamped) waveform height in px. */
  waveformHeight: number;
  /** Panel/waveform bounds for the current breakpoint — these drive the
      separator aria-valuemin/max contract. */
  propertiesMin: number;
  propertiesMax: number;
  waveformMin: number;
  waveformMax: number;
  setPropertiesOpen(open: boolean): void;
  /** Request a new docked width; stored raw, rendered clamped. */
  requestPropertiesWidth(px: number): void;
  requestWaveformHeight(px: number): void;
  resetPropertiesWidth(): void;
  resetWaveformHeight(): void;
}

export function useWorkspaceLayout(): WorkspaceLayout {
  const [stored, setStored] = useState<PersistedLayout>(loadLayout);
  const viewport = useViewportSize();
  const breakpoint = breakpointForWidth(viewport.width);

  const update = useCallback((patch: PersistedLayout) => {
    setStored((prev) => {
      const next = { ...prev, ...patch };
      saveLayout(next);
      return next;
    });
  }, []);

  const range = propertiesRange(breakpoint);
  const propertiesWidth = clampPropertiesWidth(
    stored.propertiesWidth ?? range.fallback,
    breakpoint,
  );
  const waveformHeight = clampWaveformHeight(
    stored.waveformHeight ?? WAVEFORM_DEFAULT,
    viewport.height,
  );

  return {
    breakpoint,
    // §6: closed while nothing is selected; user can reopen via the
    // command-bar overflow menu. EMPTY never mounts the region at all.
    propertiesOpen: stored.propertiesOpen ?? false,
    propertiesWidth,
    waveformHeight,
    propertiesMin: range.min,
    propertiesMax: range.max,
    waveformMin: WAVEFORM_MIN,
    waveformMax: waveformMaxHeight(viewport.height),
    setPropertiesOpen: useCallback(
      (open: boolean) => update({ propertiesOpen: open }),
      [update],
    ),
    requestPropertiesWidth: useCallback(
      (px: number) => update({ propertiesWidth: px }),
      [update],
    ),
    requestWaveformHeight: useCallback(
      (px: number) => update({ waveformHeight: px }),
      [update],
    ),
    resetPropertiesWidth: useCallback(
      () => update({ propertiesWidth: propertiesRange(breakpoint).fallback }),
      [update, breakpoint],
    ),
    resetWaveformHeight: useCallback(
      () => update({ waveformHeight: WAVEFORM_DEFAULT }),
      [update],
    ),
  };
}

/**
 * Pointer drag-resize for the panel separators. `toValue` maps a pointer
 * position to the requested size; `apply` receives it on every move.
 * Keyboard resize is handled by the separators themselves via
 * `resizeKeyDelta` (±8px on the 4px grid).
 */
export function startPointerResize(
  e: React.PointerEvent,
  apply: (value: number) => void,
  toValue: (clientX: number, clientY: number) => number,
): void {
  e.preventDefault();
  const move = (ev: PointerEvent) => apply(toValue(ev.clientX, ev.clientY));
  const up = () => {
    window.removeEventListener("pointermove", move);
    window.removeEventListener("pointerup", up);
  };
  window.addEventListener("pointermove", move);
  window.addEventListener("pointerup", up);
}

/** Arrow-key resize delta for separators (grows on ←/↑, shrinks on →/↓). */
export function resizeKeyDelta(
  e: React.KeyboardEvent,
  base: number,
): number | null {
  if (e.key === "ArrowLeft" || e.key === "ArrowUp") return base - 8;
  if (e.key === "ArrowRight" || e.key === "ArrowDown") return base + 8;
  return null;
}
